        searcher: &Searcher,
        bytes: &[u8],
        range: std::ops::Range<usize>,
    ) -> io::Result<()> {
        self.replacer.clear();
        let replacement = Arc::clone(&self.standard.config.replacement);
        if let Some(ref replacement) = *replacement {
