#[cfg(feature = "pcre2")]
fn matcher_pcre2(&self, patterns: &[String]) -> Result<PCRE2RegexMatcher> {
    let mut builder = PCRE2RegexMatcherBuilder::new();
    builder
        .case_smart(self.case_smart())
        .caseless(self.case_insensitive())
        .multi_line(true)
        .word(self.is_present("word-regexp"));
