fn replace_all(
    &mut self,
    searcher: &Searcher,
    mut subject: &[u8],
    range: std::ops::Range<usize>,
    replacement: &[u8],
) -> io::Result<()> {
    // See the giant comment in `find_iter_at_in_context` for why we do
    // this dance. Multi-line replacement depends on the searcher's
    // configured multi-line mode and line terminator, plus whether the
    // matcher itself can produce matches that span those terminators.
    let is_multi_line = searcher.multi_line()
        && searcher.multi_line_with_matcher(&self.matcher);
    if is_multi_line {
        if subject[range.end..].len() >= MAX_LOOK_AHEAD {
            subject = &subject[..range.end + MAX_LOOK_AHEAD];
        }
    } else {
        // When searching a single line, we should remove the line
        // terminator. Otherwise, it's possible for the regex (via
        // look-around) to observe the line terminator and not match
        // because of it.
        let mut m = Match::new(0, range.end);
        subject = &subject[..trim_line_terminator(
            searcher.line_terminator(),
            subject,
            &mut m,
        )];
    }
    let matcher = &self.matcher;
    self.replacer.allocate(matcher)?;
    self.replacer.dst.clear();
    self.replacer.matches.clear();
    {
        let caps = self.replacer.caps.as_mut().unwrap();
        let dst = &mut self.replacer.dst;
        let matches = &mut self.replacer.matches;
        matcher
            .replace_with_captures_at(
                subject,
                range.start,
                caps,
                dst,
                |caps, dst| {
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                },
            )
            .map_err(io::Error::error_message)?;
    }
    Ok(())
}

